import math

def priority(item: float, remaining_capacity: float, bin_capacity: float) -> float:
    """Assigns priority to placing `item` into a bin with given remaining capacity.
    Higher priority indicates a more desirable placement.
    """
    # Check feasibility with a small tolerance for floating‑point errors
    if remaining_capacity < item - 1e-12:
        return -math.inf
    if remaining_capacity <= 0:
        return -math.inf

    # Priority = (item / remaining_capacity) * ((bin_capacity - remaining_capacity) / bin_capacity)
    # This favors bins where the item fits snugly and the bin is already partially used.
    return (item * (bin_capacity - remaining_capacity)) / (remaining_capacity * bin_capacity)

import math

def priority(item: float, remaining_capacity: float, bin_capacity: float) -> float:
    # If the item does not fit, give the lowest possible priority
    if item > remaining_capacity + 1e-12:
        return -math.inf

    leftover = remaining_capacity - item          # unused space after placing the item
    desired_free = bin_capacity * 0.1             # target free space (10% of bin capacity)

    # Higher priority (closer to zero) when leftover is near the desired free space.
    # Negative absolute deviation ensures that larger deviations give lower priority.
    return -abs(leftover - desired_free)
